const item = $input.item.json;
const from = String(item.from || '').trim();
const subject = String(item.subject || '').trim();
const body = String(item.body || '');
const receivedAt = item.receivedAt || item.received || null;
const approval = item.approval && item.approval.approved === true;

const empty = body.trim().length === 0;
const hay = subject + '\n' + body;
const billing = /\b(invoice|invoices|billing|billed|charge[ds]?|refund|payment|credit memo|double[- ]charg|setup fee|ap team)\b/i.test(hay);
const bug = /\b(bug|broken|crash(?:es|ed)?|error|truncat(?:e|es|ed|ion)|doesn'?t work|not working|repro)\b/i.test(hay);
const feature = /\b(can we|could we|feature|request|would it be possible|wishlist|add(?:ing)?|filter[s]?)\b/i.test(hay);
const praise = /\b(thank(?:s| you)?|excellent|love|great|awesome|amazing|no action(?: needed)?)\b/i.test(hay);

let category = 'Ambiguous';
let priority = 'Medium';
let inboxStatus = 'Classified';
let reason = 'No category keywords matched.';

if (empty) {
  reason = 'Empty body held for human triage before task upsert.';
} else if (billing) {
  category = 'Billing'; priority = 'High'; inboxStatus = 'Tasked'; reason = 'Billing keywords matched.';
} else if (bug) {
  category = 'Bug'; priority = 'High'; inboxStatus = 'Tasked'; reason = 'Bug keywords matched.';
} else if (feature) {
  category = 'Feature request'; priority = 'Medium'; inboxStatus = 'Tasked'; reason = 'Feature-request keywords matched.';
} else if (praise) {
  category = 'Praise'; priority = 'Low'; inboxStatus = 'Closed'; reason = 'Praise keywords matched.';
}

let summary;
if (empty) {
  summary = 'Empty body / bounce-like sender; held for human triage before task upsert.';
} else {
  const cleaned = body.replace(/\s+/g, ' ').trim();
  const m = cleaned.match(/.*?[.!?](?:\s|$)/);
  summary = (m ? m[0] : cleaned).trim().slice(0, 180);
}

return {
  id: item.id || null,
  from,
  subject,
  body,
  receivedAt,
  channel: item.channel || 'mock-ingest',
  approvalApproved: approval,
  approvedBy: item.approval && item.approval.approvedBy || null,
  category,
  priority,
  inboxStatus,
  reason,
  summary,
  emptyBody: empty,
};

const j = $input.item.json;
const inboxDb = 'e7ef4cee56c14c42a2976b82980830a8';
const tasksDb = '9bc2938020014c3182bacca4f626bc3f';
const retriesDb = '6e7d1e89ed5a40c38a3a838647a22f4f';

const title = (c) => ({ title: [{ type: 'text', text: { content: String(c || '').slice(0, 2000) } }] });
const rich = (c) => ({ rich_text: [{ type: 'text', text: { content: String(c || '').slice(0, 2000) } }] });
const sel = (n) => ({ select: { name: n } });
const dateOnly = (v) => {
  if (!v) return new Date().toISOString().slice(0, 10);
  const d = new Date(v);
  if (Number.isNaN(d.getTime())) {
    const m = String(v).match(/\d{4}-\d{2}-\d{2}/);
    return m ? m[0] : new Date().toISOString().slice(0, 10);
  }
  return d.toISOString().slice(0, 10);
};

const inbox = {
  parent: { database_id: inboxDb },
  properties: {
    Subject: title(j.subject || '(no subject)'),
    From: { email: j.from || null },
    Category: sel(j.category),
    Priority: sel(j.priority),
    Status: sel(j.inboxStatus),
    Summary: rich(j.summary),
    Received: { date: { start: dateOnly(j.receivedAt) } },
  },
};

const createTask = j.category !== 'Ambiguous';
let task = null;
if (createTask) {
  const approved = j.approvalApproved === true;
  const praise = j.category === 'Praise';
  const status = praise ? 'Done' : approved ? 'Approved' : 'Waiting approval';
  const needed = praise || approved ? false : true;
  let taskTitle = j.subject || 'Triage feedback';
  if (j.category === 'Bug' && /truncat/i.test(j.subject)) taskTitle = 'Fix CSV product-name truncation';
  if (j.category === 'Feature request') taskTitle = 'Roadmap: portal feedback tag filters';
  if (j.category === 'Billing') taskTitle = 'Issue credit memo for double setup fee';
  if (j.category === 'Praise') taskTitle = 'Archive praise — Harbor Apps';

  task = {
    parent: { database_id: tasksDb },
    properties: {
      Task: title(taskTitle),
      Status: sel(status),
      'Approval needed': { checkbox: needed },
      'Next action': rich(j.category === 'Billing'
        ? 'Confirm credit memo issued; close after AP confirms.'
        : j.category === 'Bug'
          ? 'Engineering triage; draft ETA for the reporter.'
          : j.category === 'Feature request'
            ? 'Add to roadmap; soft acknowledge.'
            : 'No reply needed; archive praise for CS metrics.'),
      'Reply draft': rich('(see src/feedback-ops.mjs — mock draft, never sent)'),
    },
  };
}

return {
  ...j,
  notion: { inbox, task, retriesDb },
  createTask,
};

const j = $input.item.json;
return {
  ...j,
  sendGate: {
    approved: true,
    sent: false,
    blockedReason: 'Send skipped: mock mode — sent is always false even after human approval.',
    channel: null,
  },
  sent: false,
};

const j = $input.item.json;
const praise = j.category === 'Praise';
return {
  ...j,
  sendGate: {
    approved: false,
    sent: false,
    blockedReason: praise
      ? 'Send gate skipped: praise archived, no send required. Mock never sends.'
      : 'Send gate blocked: Approval needed still checked. No email sent (by design).',
    channel: null,
  },
  sent: false,
};

const j = $input.item.json;
const retriesDb = (j.notion && j.notion.retriesDb) || '6e7d1e89ed5a40c38a3a838647a22f4f';
const title = (c) => ({ title: [{ type: 'text', text: { content: String(c || '').slice(0, 2000) } }] });
const rich = (c) => ({ rich_text: [{ type: 'text', text: { content: String(c || '').slice(0, 2000) } }] });
const dateOnly = (v) => {
  if (!v) return new Date().toISOString().slice(0, 10);
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? String(v).slice(0, 10) : d.toISOString().slice(0, 10);
};

const retries = [];
if (j.emptyBody || j.category === 'Ambiguous') {
  retries.push({
    parent: { database_id: retriesDb },
    properties: {
      Event: title('Empty body — classify skipped'),
      Stage: { select: { name: 'Classify' } },
      Error: rich('Classifier returned empty-body hold; routed to human triage.'),
      'Retry count': { number: 0 },
      Resolved: { checkbox: false },
      Occurred: { date: { start: dateOnly(j.receivedAt) } },
    },
  });
}

const reason = j.sendGate && j.sendGate.blockedReason;
if (reason) {
  retries.push({
    parent: { database_id: retriesDb },
    properties: {
      Event: title(j.sendGate.approved ? 'Send skipped (mock never sends)' : 'Send gate blocked (approval)'),
      Stage: { select: { name: 'Send gate' } },
      Error: rich(reason),
      'Retry count': { number: 0 },
      Resolved: { checkbox: true },
      Occurred: { date: { start: dateOnly(j.receivedAt) } },
    },
  });
}

return {
  ...j,
  notion: { ...(j.notion || {}), retries },
  sent: false,
};
